  page.locator('#list [data-open="sort-fictif-3"]').click();expect(page.locator('#detailTitle')).to_contain_text('Bravo fictif');page.locator('#edit').click();f=page.locator('#equipmentForm');owner=f.locator('[name=owner]');expect(owner).to_have_attribute('required','');f.locator('[name=location]').fill('Atelier test');f.get_by_role('button',name='Enregistrer l’équipement',exact=True).click();expect(page.locator('#ownerRequiredError')).to_contain_text('Choisissez un propriétaire');expect(page.locator('#editor')).to_be_visible();assert json.loads(page.evaluate('localStorage.getItem("vgp-prototype-v1")'))==source
